static const struct element_type_map *hubbub_element_type_generated_lookup(const char *s, size_t len)
{
	int lo = 0, hi = (int)(sizeof(wordlist) / sizeof(wordlist[0])) - 1;
	char b[32];
	size_t i;
	if (len == 0 || len >= sizeof(b)) return NULL;
	for (i = 0; i < len; i++) b[i] = (s[i] >= 'A' && s[i] <= 'Z') ? s[i] + 32 : s[i];
	b[len] = 0;
	while (lo <= hi) {
		int m = (lo + hi) / 2, c = strcmp(b, wordlist[m].name);
		if (c == 0) return &wordlist[m];
		if (c < 0) hi = m - 1; else lo = m + 1;
	}
	return NULL;
}
